// =============================================================================
//  The team's product sheets → the one store, as ParentVeda's shortlist
// -----------------------------------------------------------------------------
//  2026-10-13. The Drive folder "Products", generated by
//  `tools/products/xlsx_to_dart.py` into `sheet/catalogue.dart` and
//  `sheet/toys.dart`. Never hand-edit those; fix the sheet and re-run.
//
//  THE USER'S DECISIONS (2026-10-13)
//    · No price, link or photo in the sheets: shown as ParentVeda's SHORTLIST
//      — brand, product, a Budget/Premium tag, the sheet's "decision factors"
//      as the shelf's "what to look for", "Price varies", no buy button, an
//      honest cover. Nothing invented to fill the gaps.
//    · Where a sheet covers a category the store already had, the sheet's
//      picks LEAD and the older products stay below (the shelf's sort, see
//      `pvShortlistFirst`). Nothing removed.
//    · Toy scores RANK the shelf and are SHOWN ("essential to make judgment").
//    · HELD: the fetal-doppler and herbal-tea shelves conflict with the app's
//      clinical stance and stay out until signed off ([kSheetSubsSignedOff]).
//
//  ⚠️ THE STAGE IS WHERE SHE SHOPS. Every catalogue pick — nursery gear too —
//  is a pregnancy product, because the sheet's own "buy by" week is in
//  pregnancy; `weekFrom` carries it, so "For you right now" offers each one
//  near its week. Toys are parenting, by age.
// =============================================================================

import '../../models/pv_product.dart';
import '../book_companions.dart' show BookDoc, kBookDocList;
import '../../services/life_stage_store.dart';
import 'sheet/catalogue.dart';
import 'sheet/toys.dart';

enum SheetBucket { pregnancy, hospital, nursery }

/// One pick from the Pregnancy and Parenting Product Catalogue.
class SheetPick {
  const SheetPick(this.id, this.bucket, this.category, this.sub, this.factors, this.tier, this.brand,
      this.name, this.week,
      {this.held = false});
  final String id;
  final SheetBucket bucket;
  final String category;
  final String sub;

  /// The sheet's "decision factors" for the sub-category, split into lines.
  final List<String> factors;

  /// budget | premium | book | unsplit.
  final String tier;
  final String brand;
  final String name;

  /// The sheet's "Target Purchase Timeline" week.
  final int week;
  final bool held;
}

/// One toy from the Products Master or the 0–5 master.
class SheetToy {
  const SheetToy({
    required this.id,
    required this.name,
    required this.brand,
    required this.category,
    required this.sub,
    required this.tier,
    required this.skills,
    required this.score,
    required this.confidence,
    this.ageMin,
    this.ageMax,
    this.ageLabel = '',
    this.subScores = const [],
  });
  final String id;
  final String name;

  /// Empty when the sheet names a kind of toy rather than a maker.
  final String brand;
  final String category;
  final String sub;
  final String tier;
  final List<String> skills;
  final int? score;
  final int confidence;
  final int? ageMin;
  final int? ageMax;
  final String ageLabel;
  final List<(String, int)> subScores;
}

/// ⚠️ THE CLINICAL SIGN-OFF for held shelves. A held sub-category goes live
/// only when its name is here, one line each with the date and who signed.
const Set<String> kSheetSubsSignedOff = {};

bool _live(SheetPick p) => !p.held || kSheetSubsSignedOff.contains(p.sub);

String _slug(String s) => s
    .toLowerCase()
    .replaceAll('&', 'and')
    .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
    .replaceAll(RegExp(r'^_|_$'), '');

// ---- where each sheet sub-category lives ------------------------------------------

/// Sheet sub-categories that ARE a category the store already had: their picks
/// join it and lead it. Checked by eye, 2026-10-13. Everything else is a
/// category of the sheet's own.
const Map<String, String> kSheetSubIntoCategory = {
  'Ergonomic Pregnancy Pillows': 'pregnancy_pillow',
  'Stretch Mark Butters & Oils': 'stretch_care',
  'Maternity Compression Socks': 'compression_socks',
  'Wireless Nursing Bras': 'nursing_bra',
  'Electric Breast Pumps': 'breast_pump',
  'Muslin Swaddle Cloths': 'swaddle',
};

/// The store category id a pick lives in.
String sheetCategoryIdFor(SheetPick p) => kSheetSubIntoCategory[p.sub] ?? 'pvs_${_slug(p.category)}';

String sheetSubId(String sub) => 'pvs_${_slug(sub)}';

/// Toys join the parenting "Play & Development" category, under the sheet's
/// own toy categories as its sub-categories.
const String kSheetToyCategoryId = 'play_and_development';

String sheetToySubId(SheetToy t) => 'pvt_${_slug(t.category)}';

// ---- categories ---------------------------------------------------------------------

const double _hueSheet = 26;

PvGuidance _guide(List<String> factors) => PvGuidance(line: '', lookFor: factors, avoid: const []);

/// The sheet's own pregnancy categories, in the sheet's order, with their
/// sub-categories and each sub's "what to look for".
List<PvCategory> sheetCategories() {
  final order = <String>[];
  final subs = <String, List<SheetPick>>{};
  for (final p in kSheetPicks) {
    if (!_live(p) || kSheetSubIntoCategory.containsKey(p.sub)) continue;
    final id = sheetCategoryIdFor(p);
    if (!subs.containsKey(id)) order.add(id);
    (subs[id] ??= []).add(p);
  }
  return [
    for (final id in order)
      PvCategory(
        id: id,
        stage: LifeStage.pregnancy,
        name: subs[id]!.first.category,
        hue: _hueSheet,
        subs: [
          for (final s in {for (final p in subs[id]!) p.sub}) PvSub(sheetSubId(s), s),
        ],
        subGuidance: {for (final p in subs[id]!) sheetSubId(p.sub): _guide(p.factors)},
        fromWeek: subs[id]!.map((p) => p.week).reduce((a, b) => a < b ? a : b),
      ),
  ];
}

/// The sub-categories a sheet adds to a category the store already had.
List<PvSub> sheetSubsInto(String categoryId) => [
      for (final s in {
        for (final p in kSheetPicks)
          if (_live(p) && kSheetSubIntoCategory[p.sub] == categoryId) p.sub
      })
        PvSub(sheetSubId(s), s),
    ];

Map<String, PvGuidance> sheetGuidanceInto(String categoryId) => {
      for (final p in kSheetPicks)
        if (_live(p) && kSheetSubIntoCategory[p.sub] == categoryId) sheetSubId(p.sub): _guide(p.factors),
    };

/// The toy sub-categories, in the sheets' order.
List<PvSub> sheetToySubs() => [
      for (final c in {for (final t in kSheetToys) t.category}) PvSub('pvt_${_slug(c)}', c),
    ];

// ---- products -----------------------------------------------------------------------

String _tierBadge(String tier) => switch (tier) {
      'budget' => 'Budget pick',
      'premium' => 'Premium pick',
      'mid' => 'Mid-range pick',
      'book' => 'Book',
      _ => 'Shortlisted',
    };

PvProduct _fromPick(SheetPick p) => PvProduct(
      id: p.id,
      stage: LifeStage.pregnancy,
      categoryId: sheetCategoryIdFor(p),
      subId: sheetSubId(p.sub),
      name: p.name,
      brand: p.brand,
      priceNote: 'Price varies',
      badge: _tierBadge(p.tier),
      weekFrom: p.week,
      forPartner: p.category == "Father's Corner",
      // The sheet's factors describe the whole sub-category, not this product:
      // they show as "what the team looked for" (the shelf's guidance), never
      // as this product's own claims.
      hue: _hueSheet,
      shortlist: true,
    );

PvProduct _fromToy(SheetToy t) => PvProduct(
      id: t.id,
      stage: LifeStage.parenting,
      categoryId: kSheetToyCategoryId,
      subId: sheetToySubId(t),
      name: t.name,
      brand: t.brand,
      priceNote: 'Price varies',
      badge: _tierBadge(t.tier),
      ageMinMonths: t.ageMin ?? 0,
      ageMaxMonths: t.ageMax ?? 72,
      specs: [if (t.ageLabel.isNotEmpty) ('Age', t.ageLabel), if (t.sub.isNotEmpty) ('Type', t.sub)],
      hue: 344,
      shortlist: true,
      score: t.score,
      confidence: t.confidence,
      scoreParts: t.subScores,
      skills: t.skills,
    );

/// Every live sheet product, for `buildPvCatalog()`.
List<PvProduct> sheetProducts() => [
      for (final p in kSheetPicks)
        if (_live(p)) _fromPick(p),
      for (final t in kSheetToys) _fromToy(t),
    ];

String _norm(String s) =>
    s.toLowerCase().replaceAll('’', "'").replaceAll(RegExp(r"[^a-z0-9' ]+"), ' ').replaceAll(RegExp(r'\s+'), ' ').trim();

/// The ParentVeda book companion for a shortlisted BOOK pick, or null. The
/// sheet's title must begin with the companion's whole title ("Expecting
/// Better: Why Conventional…" → "Expecting Better"); anything looser stays a
/// product, because a wrong companion is worse than none.
BookDoc? sheetBookCompanionFor(PvProduct p) {
  if (!p.shortlist || p.badge != 'Book') return null;
  final name = _norm(p.name);
  for (final d in kBookDocList) {
    final t = _norm(d.title);
    if (t.length >= 8 && (name == t || name.startsWith('$t '))) return d;
  }
  return null;
}

/// The shelf's order for the shortlist: the team's picks first, the highest
/// score, then the highest confidence, then the sheet's own order (a stable
/// sort keeps it); everything else after, in its existing order.
int pvShortlistFirst(PvProduct a, PvProduct b) {
  if (a.shortlist != b.shortlist) return a.shortlist ? -1 : 1;
  if (!a.shortlist) return 0;
  final s = (b.score ?? -1).compareTo(a.score ?? -1);
  if (s != 0) return s;
  return (b.confidence ?? 0).compareTo(a.confidence ?? 0);
}
